=== Scenario.java ===
import java.util.ArrayList;
import java.util.List;

/**
 * A customer's dealings with the MHPCO, worked through in order.
 *
 * <p>Knows that the steps of a scenario are settled sequentially for a single
 * customer, and that each step is settled against the running record of the
 * steps before it. Defers what that record carries to the scenario ledger,
 * and knows nothing about the wire format a scenario arrived in or its
 * results are written back in.
 */
final class Scenario {

    private final Customer customer;
    private final List<Step> steps;

    Scenario(Customer customer, List<Step> steps) {
        this.customer = customer;
        this.steps = List.copyOf(steps);
    }

    /**
     * The result of every step, in the order the MHPCO worked through them.
     */
    List<StepResult> settle() {
        List<StepResult> results = new ArrayList<>();
        ScenarioLedger ledger = new ScenarioLedger();
        for (int index = 0; index < steps.size(); index++) {
            results.add(settle(steps.get(index), index, ledger));
        }
        return results;
    }

    private StepResult settle(Step step, int index, ScenarioLedger ledger) {
        if (step instanceof ClaimStep claim) {
            return settle(claim, ledger);
        }
        return settle((QuoteStep) step, index, ledger);
    }

    private StepResult settle(QuoteStep quote, int index, ScenarioLedger ledger) {
        int premium = PremiumCalculator.premiumFor(
                customer, ledger.concludedContracts(), quote.items());
        ledger.recordPolicy(index, new Policy(quote.items()));
        return new QuoteResult(premium);
    }

    private StepResult settle(ClaimStep claim, ScenarioLedger ledger) {
        Policy policy = ledger.policyWrittenBy(claim.policy());
        return ClaimResult.of(policy.settle(claim.incident()), policy.remainingCap());
    }
}
=== ScenarioLedger.java ===
import java.util.HashMap;
import java.util.Map;

/**
 * The running record the MHPCO carries from one step of a scenario to the
 * next.
 *
 * <p>Holds two readings of how the steps of a scenario bear on one another.
 * Every contract concluded before a step makes that step a follow-up
 * contract, so the ledger counts them as it goes. And a claim names the
 * policy it is made against by the zero-based index of the quote step that
 * wrote it, so the ledger files each policy under that index.
 *
 * <p>Changes whenever the MHPCO revises what one step of a scenario means for
 * the next; knows nothing about tariffs, payouts or the wire format.
 */
final class ScenarioLedger {

    private final Map<Integer, Policy> policiesByQuoteStep = new HashMap<>();
    private int concludedContracts;

    /**
     * Files the policy a quote step wrote under that step's index, and counts
     * the contract as concluded.
     */
    void recordPolicy(int quoteStepIndex, Policy policy) {
        policiesByQuoteStep.put(quoteStepIndex, policy);
        concludedContracts++;
    }

    /**
     * The policy a claim names by the index of the quote step that wrote it.
     */
    Policy policyWrittenBy(int quoteStepIndex) {
        return policiesByQuoteStep.get(quoteStepIndex);
    }

    /**
     * How many contracts the customer had already concluded in this scenario.
     */
    int concludedContracts() {
        return concludedContracts;
    }
}
=== Policy.java ===
import java.math.BigDecimal;
import java.util.List;

/**
 * A policy the MHPCO has written over a list of items.
 *
 * <p>Knows which items it covers, and that settling an incident means paying
 * what is owed for it as far as the policy's payout cap allows. Defers what is
 * owed to the reimbursement rules and how far the cap allows to the cap
 * itself.
 */
final class Policy {

    private final List<Item> items;
    private final PayoutCap cap;

    Policy(List<Item> items) {
        this.items = List.copyOf(items);
        this.cap = new PayoutCap(this.items);
    }

    BigDecimal remainingCap() {
        return cap.remaining();
    }

    /**
     * Settles an incident against this policy, reducing the remaining cap by
     * what is paid out.
     */
    BigDecimal settle(Incident incident) {
        return cap.draw(Reimbursement.of(items, incident));
    }
}

=== ScenarioJson.java ===
import com.fasterxml.jackson.databind.JsonNode;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Translates between the MHPCO wire format and the domain.
 *
 * <p>Changes whenever the JSON schema of a scenario or of a results document
 * changes; knows nothing about tariffs, premiums or the command line.
 */
final class ScenarioJson {

    private ScenarioJson() {
    }

    static Scenario scenarioOf(JsonNode scenario) {
        List<Step> steps = new ArrayList<>();
        for (JsonNode step : scenario.get("steps")) {
            steps.add(stepOf(step));
        }
        return new Scenario(customerOf(scenario), steps);
    }

    private static Step stepOf(JsonNode step) {
        if ("claim".equals(step.get("op").asText())) {
            return new ClaimStep(step.get("policy").asInt(), incidentOf(step.get("incident")));
        }
        return new QuoteStep(itemsOf(step));
    }

    private static Incident incidentOf(JsonNode incident) {
        List<Damage> damages = new ArrayList<>();
        for (JsonNode damage : incident.get("damages")) {
            damages.add(new Damage(damage.get("itemType").asText(), damage.get("amount").asInt()));
        }
        return new Incident(incident.get("cause").asText(), damages);
    }

    private static List<Item> itemsOf(JsonNode quoteStep) {
        List<Item> items = new ArrayList<>();
        for (JsonNode item : quoteStep.get("items")) {
            items.add(new Item(item.get("type").asText(), item.path("enchantment").asInt(),
                    item.path("cursed").asBoolean()));
        }
        return items;
    }

    private static Customer customerOf(JsonNode scenario) {
        return new Customer(scenario.get("customer").get("yearsWithMHPCO").asInt());
    }

    static String results(List<StepResult> results) {
        return "{\"results\":[" + results.stream()
                .map(ScenarioJson::resultOf)
                .collect(Collectors.joining(",")) + "]}";
    }

    private static String resultOf(StepResult result) {
        if (result instanceof ClaimResult claim) {
            return "{\"payout\":" + claim.payout()
                    + ",\"remainingCap\":" + claim.remainingCap() + "}";
        }
        return "{\"premium\":" + ((QuoteResult) result).premium() + "}";
    }
}
=== Reimbursement.java ===
import java.math.BigDecimal;
import java.util.List;

/**
 * What the MHPCO reimburses for an incident, before the policy's cap is
 * applied.
 *
 * <p>Knows that a deductible applies per damage event — once for each damaged
 * item — and that it is taken off after the clauses have said how much of the
 * damage is reimbursed at all. Defers which item a damage entry names, and
 * what the clauses make of it, to those two.
 */
final class Reimbursement {

    private static final BigDecimal DEDUCTIBLE_IN_G = BigDecimal.valueOf(100);

    private Reimbursement() {
    }

    static BigDecimal of(List<Item> insured, Incident incident) {
        BigDecimal reimbursement = BigDecimal.ZERO;
        for (DamagedItem damaged : DamagedItem.of(insured, incident.damages())) {
            reimbursement = reimbursement.add(reimbursementFor(damaged));
        }
        return reimbursement;
    }

    private static BigDecimal reimbursementFor(DamagedItem damaged) {
        BigDecimal damage = BigDecimal.valueOf(damaged.damage().amount());
        return DamageClause.reimbursedPartOf(damaged.insured(), damage)
                .subtract(DEDUCTIBLE_IN_G)
                .max(BigDecimal.ZERO);
    }
}
=== DamageClause.java ===
import java.math.BigDecimal;

/**
 * The MHPCO's clauses on how much of a damage it reimburses at all, before the
 * deductible is taken off.
 *
 * <p>Damage to a highly enchanted item is reimbursed at only half the damage
 * amount: enchantments are held to be part of the risk the customer brought.
 *
 * <p>The MHPCO also holds that damage to an item of dragon material is fully
 * reimbursed. That clause has no branch here, and deliberately so: full
 * reimbursement is already what this class does when no clause bears on a
 * damage, and wherever the MHPCO has said what happens when both clauses meet,
 * the high-enchantment clause wins. Dragon material therefore never moves a
 * payout, and an item's material is not carried into the domain at all. Should
 * the MHPCO ever let dragon material override the half reimbursement, or
 * recognise a clause that reimburses at less than the full amount, the material
 * would have to be read from the report and a clause added here.
 */
final class DamageClause {

    private static final int HALF_REIMBURSEMENT_FROM_ENCHANTMENT = 8;
    private static final Percentage HALF_REIMBURSEMENT = Percentage.of(50);

    private DamageClause() {
    }

    static BigDecimal reimbursedPartOf(Item damaged, BigDecimal damage) {
        if (isHighlyEnchanted(damaged)) {
            return HALF_REIMBURSEMENT.ofAmount(damage);
        }
        return damage;
    }

    private static boolean isHighlyEnchanted(Item damaged) {
        return damaged.enchantment() >= HALF_REIMBURSEMENT_FROM_ENCHANTMENT;
    }
}
=== PayoutCap.java ===
import java.math.BigDecimal;
import java.util.List;

/**
 * The ceiling the MHPCO puts on what one policy ever pays out, and what is
 * left of it.
 *
 * <p>The MHPCO pays out at most twice the insurance sum over the whole life of
 * a policy. The cap is measured against the unmodified insurance sum: the
 * premium modifiers and the building block offer bear on what the customer
 * pays, never on what the MHPCO is willing to pay back. Once the cap is
 * exhausted a claim is reduced to whatever is left of it rather than refused.
 *
 * <p>Changes whenever the MHPCO revises how far it will go for a single
 * policy; knows nothing about which items are covered or what an incident is
 * worth before the cap bears on it.
 */
final class PayoutCap {

    private static final BigDecimal CAP_MULTIPLE = BigDecimal.valueOf(2);

    private BigDecimal remaining;

    PayoutCap(List<Item> items) {
        this.remaining = InsuranceSum.of(items).multiply(CAP_MULTIPLE);
    }

    /**
     * What is still available to pay out under this policy.
     */
    BigDecimal remaining() {
        return remaining;
    }

    /**
     * Draws the owed amount against the cap, returning what the cap allows and
     * reducing what is left by exactly that much.
     */
    BigDecimal draw(BigDecimal owed) {
        BigDecimal allowed = owed.min(remaining);
        remaining = remaining.subtract(allowed);
        return allowed;
    }
}
=== InsuranceSum.java ===
import java.math.BigDecimal;
import java.util.List;

/**
 * The insurance sum a policy covers: the sum of the insurance values of its
 * items.
 *
 * <p>Insurance values are the MHPCO's unmodified valuations. Neither the
 * premium modifiers nor the building block offer bear on them.
 */
final class InsuranceSum {

    private InsuranceSum() {
    }

    static BigDecimal of(List<Item> items) {
        return items.stream()
                .map(PriceList::insuranceValueFor)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
=== PremiumCalculator.java ===
import java.math.BigDecimal;
import java.util.List;

/**
 * Assembles the MHPCO premium for the items of a quote.
 *
 * <p>Knows that a premium is the policy base premium plus the risk surcharges
 * the insured items carry plus the policy-wide modifiers the customer's
 * standing earns plus the processing fee charged on every premium, and that
 * the intermediate amounts are kept as fractions until the premium is
 * settled to whole G. Defers what settling in the MHPCO's favour means to the
 * MHPCO's settlement rule.
 */
final class PremiumCalculator {

    private static final BigDecimal PROCESSING_FEE_IN_G = BigDecimal.valueOf(5);

    private PremiumCalculator() {
    }

    static int premiumFor(Customer customer, int precedingContracts, List<Item> items) {
        BigDecimal policyBasePremium = PolicyBasePremium.of(items);
        BigDecimal premium = policyBasePremium
                .add(RiskSurcharges.of(items))
                .add(PolicyModifiers.of(customer, precedingContracts, policyBasePremium))
                .add(PROCESSING_FEE_IN_G);
        return WholeG.premium(premium);
    }
}
=== PolicyBasePremium.java ===
import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Collectors;

/**
 * The base premium the MHPCO tariffs a whole quote at.
 *
 * <p>Knows that the items of a quote are tariffed in groups of alike items and
 * that the policy base premium is the sum over those groups. Defers what a
 * group of alike items costs to the MHPCO's building block offer, and knows
 * nothing about the surcharges, discounts and the processing fee that turn a
 * base premium into a premium.
 *
 * <p>Holds the MHPCO's reading of "alike": items are alike when they are of
 * the same type, not merely of the same family. Two runes and a moonstone are
 * therefore two groups, not one group of gemstone-y things.
 */
final class PolicyBasePremium {

    private PolicyBasePremium() {
    }

    static BigDecimal of(List<Item> items) {
        return items.stream()
                .collect(Collectors.groupingBy(Item::type))
                .values().stream()
                .map(BuildingBlock::basePremiumFor)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
=== InsurableRisk.java ===
import java.util.Arrays;
import java.util.List;

/**
 * The risks the MHPCO recognises as insurable on a single item, and what each
 * is surcharged at.
 *
 * <p>Each constant knows one risk: how to tell whether an item carries it, and
 * the percentage of that item's base premium the MHPCO levies for it. Knows
 * nothing about how the surcharges of a quote are added up, nor about the
 * policy-wide modifiers (loyalty, first insurance, follow-up contract).
 *
 * <p>Grows whenever the MHPCO recognises a new insurable risk; a constant
 * changes whenever the MHPCO revises that risk's rate or the condition under
 * which it is levied.
 */
enum InsurableRisk {

    CURSE(50) {
        @Override
        boolean isCarriedBy(Item item) {
            return item.cursed();
        }
    },

    /**
     * The MHPCO reads "highly enchanted" inclusively: an item at exactly the
     * threshold already carries the risk.
     */
    HIGH_ENCHANTMENT(30) {
        private static final int HIGH_ENCHANTMENT_FROM = 5;

        @Override
        boolean isCarriedBy(Item item) {
            return item.enchantment() >= HIGH_ENCHANTMENT_FROM;
        }
    };

    private final int surchargePercent;

    InsurableRisk(int surchargePercent) {
        this.surchargePercent = surchargePercent;
    }

    static List<InsurableRisk> carriedBy(Item item) {
        return Arrays.stream(values()).filter(risk -> risk.isCarriedBy(item)).toList();
    }

    abstract boolean isCarriedBy(Item item);

    Percentage surchargeRate() {
        return Percentage.of(surchargePercent);
    }
}
=== BuildingBlock.java ===
import java.math.BigDecimal;
import java.util.List;

/**
 * The MHPCO's special offer on alike components.
 *
 * <p>Knows what a group of alike items is tariffed at: a group that forms a
 * building block carries a special base premium; any other group is tariffed
 * item by item at the price list. Knows nothing about how the items of a quote
 * are grouped or added up.
 *
 * <p>Changes whenever the MHPCO revises the offer — which groups qualify as a
 * block, or the block's special base premium.
 */
final class BuildingBlock {

    private static final int BLOCK_SIZE = 3;
    private static final BigDecimal BLOCK_BASE_PREMIUM_IN_G = BigDecimal.valueOf(60);

    private BuildingBlock() {
    }

    static BigDecimal basePremiumFor(List<Item> alike) {
        if (formsABlock(alike)) {
            return BLOCK_BASE_PREMIUM_IN_G;
        }
        return alike.stream()
                .map(PriceList::basePremiumFor)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private static boolean formsABlock(List<Item> alike) {
        return alike.size() == BLOCK_SIZE;
    }
}
=== RiskSurcharges.java ===
import java.math.BigDecimal;
import java.util.List;

/**
 * The item-specific risk surcharges the MHPCO levies on the items of a quote.
 *
 * <p>Holds the MHPCO's reading of the scope question: an item-specific
 * surcharge is a percentage of the base premium of the affected item, not of
 * the policy base premium. The surcharges of a quote are therefore the sum,
 * over its items, of every recognised risk that item carries. Defers which
 * risks exist and what each costs to the MHPCO's list of insurable risks.
 *
 * <p>Changes whenever the MHPCO revises how an item-specific surcharge is
 * measured or accumulated; knows nothing about the policy-wide modifiers
 * (loyalty, first insurance, follow-up contract), which apply to the policy
 * base premium.
 */
final class RiskSurcharges {

    private RiskSurcharges() {
    }

    static BigDecimal of(List<Item> items) {
        return items.stream()
                .map(RiskSurcharges::surchargesOn)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private static BigDecimal surchargesOn(Item item) {
        BigDecimal itemBasePremium = PriceList.basePremiumFor(item);
        return InsurableRisk.carriedBy(item).stream()
                .map(risk -> risk.surchargeRate().ofAmount(itemBasePremium))
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
=== CustomerStanding.java ===
import java.util.Arrays;
import java.util.List;

/**
 * The facts about a customer's standing with the MHPCO that bear on a premium,
 * and what each is worth.
 *
 * <p>Each constant knows one fact: how to tell whether it holds of a customer
 * at a given point in their dealings, and the percentage of the policy base
 * premium the MHPCO levies or grants for it. A surcharge is a positive rate, a
 * discount a negative one, so a standing's worth is always signed the way it
 * moves the premium.
 *
 * <p>Knows nothing about how the facts of a quote are added up, nor about the
 * item-specific risk surcharges, which are measured against the base premium of
 * a single item rather than of the whole policy.
 *
 * <p>Grows whenever the MHPCO recognises a new fact about a customer's
 * standing; a constant changes whenever the MHPCO revises that fact's rate or
 * the condition under which it holds.
 */
enum CustomerStanding {

    /**
     * Every quote is an initial assessment: each item of a quote is treated as
     * a first insurance, whatever the customer's history.
     */
    FIRST_INSURANCE(10) {
        @Override
        boolean holdsOf(Customer customer, int precedingContracts) {
            return true;
        }
    },

    /**
     * The MHPCO reads "long-standing" inclusively: a customer at exactly the
     * threshold already qualifies.
     */
    LOYALTY(-20) {
        private static final int LOYALTY_FROM_YEARS = 2;

        @Override
        boolean holdsOf(Customer customer, int precedingContracts) {
            return customer.yearsWithMHPCO() >= LOYALTY_FROM_YEARS;
        }
    },

    /**
     * Every contract after the customer's first is a follow-up contract.
     */
    FOLLOW_UP_CONTRACT(-15) {
        @Override
        boolean holdsOf(Customer customer, int precedingContracts) {
            return precedingContracts > 0;
        }
    };

    private final int ratePercent;

    CustomerStanding(int ratePercent) {
        this.ratePercent = ratePercent;
    }

    static List<CustomerStanding> of(Customer customer, int precedingContracts) {
        return Arrays.stream(values())
                .filter(standing -> standing.holdsOf(customer, precedingContracts))
                .toList();
    }

    abstract boolean holdsOf(Customer customer, int precedingContracts);

    Percentage rate() {
        return Percentage.of(ratePercent);
    }
}
=== PolicyModifiers.java ===
import java.math.BigDecimal;

/**
 * The policy-wide modifiers the MHPCO applies to a policy base premium.
 *
 * <p>Holds the MHPCO's reading of the scope question for the customer's side:
 * unlike the item-specific risk surcharges, these follow from the customer's
 * standing with the MHPCO rather than from any insured item, and they are
 * measured against the policy base premium, the sum of all item base premiums.
 * The modifiers of a quote are therefore the sum, over the facts of the
 * customer's standing, of each fact's rate of that one amount. Defers which
 * facts count and what each is worth to the MHPCO's list of customer standings.
 *
 * <p>Returns a signed amount: what the customer's standing adds to the policy
 * base premium. A discount is therefore negative.
 *
 * <p>Changes whenever the MHPCO revises how a policy-wide modifier is measured
 * or accumulated.
 */
final class PolicyModifiers {

    private PolicyModifiers() {
    }

    static BigDecimal of(Customer customer, int precedingContracts, BigDecimal policyBasePremium) {
        return CustomerStanding.of(customer, precedingContracts).stream()
